# Keys whose value the server never gives back (the contract still lists them). No key of server.cfg holds a secret today: a password, a token or a key never
# goes into server.cfg, and the keys that name a file (tls_cert_file, design_program, ...) name it, they do not hold what is inside it.
SECRET_KEYS: set[str] = set()
